        if label not in label_runs:
            label_runs[label] = 1
        else:
            label_runs[label] += 1

        # Check if the run has reached 2 and is uninterrupted
        if label_runs[label] >= 2:
            # If the run is uninterrupted and reaches 2, emit the alert
            if label not in alerts:
                alerts.append(label)
            # Reset the run if the value is lower than the previous one
            if value < label_runs[label] - 1:
                label_runs[label] = 1
            else:
                # Continue the run
                pass
        else:
            # If the run is less than 2, continue
            pass

    return alerts
