def solve(x):
    from collections import defaultdict

    label_counts = defaultdict(int)
    alerts = []

    for label, value in x:
        if value < label_counts[label]:
            label_counts[label] = 0
        label_counts[label] += 1
        if label_counts[label] == 2:
            alerts.append(label)

    return alerts
