import re

def solve(x):
    data = {}
    events = []
    for line in x.strip().split('\n'):
        if line.strip() and not line.startswith('['):
            events.append(line)
    for event in events:
        match = re.search(r'label\s*=\s*([^\s]+)', event)
        label = match.group(1)
        match = re.search(r'value\s*=\s*(\d+)', event)
        value = int(match.group(1))
        if label not in data:
            data[label] = 0
        data[label] = (data[label] + value) % 13
    return data
