import re

def solve(x):
    data = {}
    for line in x.strip().split('\n'):
        if not line.strip():
            continue
        key, value = re.findall(r'(\w+)\s*=\s*(\d+)', line)
        label, value = key[0], int(value)
        data[label] = data.get(label, 0) + 1
    result = {}
    for label in data:
        result[label] = data[label] % 13
    return result
