import json

def solve(x):
    data = json.loads(x)
    label_values = {}
    for item in data:
        label = item['label']
        value = item['value']
        if label in label_values:
            label_values[label].append(value)
        else:
            label_values[label] = [value]
    result = []
    for label in label_values:
        if sum(label_values[label]) >= 9:
            result.append(label)
    return result
