from io import StringIO

def solve(x):
    if not x.strip():
        return []

    lines = x.strip().split('\r\n')
    reader = csv.DictReader(StringIO('\r\n'.join(lines)))

    alerts = []
    label_runs = {}

    for row in reader:
        label = row['label']
        value = int(row['value'])

        if label not in label_runs:
            label_runs[label] = []

        label_runs[label].append(value)

        if len(label_runs[label]) >= 2:
            if label_runs[label][-1] < value:
                alerts.append(label)
                label_runs[label] = [value]
            else:
                label_runs[label].append(value)

    return alerts
