def solve(x):
    result = {}
    for label, value in x:
        if label not in result:
            result[label] = 0
        # Compute the forward change: (value - previous_value) % 31
        # Because the meter is cyclic from 0 to 30, a decrease wraps around
        prev = result[label]
        change = (value - prev) % 31
        result[label] += change
    return result
